import java.io.BufferedReader
import java.io.InputStreamReader
import java.util.StringTokenizer

fun divisors(num: Long): MutableList<Long> {
    val ret = mutableListOf<Long>()
    var i: Long = 2
    while (i * i < num) {
        if (num % i == 0L) {
            ret.add(i)
            ret.add(num / i)
        }
        i++
    }
    if (i * i == num) {
        ret.add(i)
    }
    return ret
}

fun main() {
    val br = BufferedReader(InputStreamReader(System.`in`))
    val sb = StringBuilder()
    var line: String?

    while (true) {
        line = br.readLine() ?: break
        if (line.isBlank()) continue
        val st = StringTokenizer(line)
        while (st.hasMoreTokens() == false) {
            line = br.readLine() ?: break
        }
        val tokens = mutableListOf<String>()
        var tempLine = line
        while (tokens.size < 3) {
            if (tempLine == null) break
            val stk = StringTokenizer(tempLine)
            while (stk.hasMoreTokens()) {
                tokens.add(stk.nextToken())
                if (tokens.size == 3) break
            }
            if (tokens.size < 3) {
                tempLine = br.readLine()
            }
        }
        if (tokens.size < 3) break

        val n = tokens[0].toLong()
        val m = tokens[1].toLong()
        val k = tokens[2].toLong()

        if (n % 2 == 0L) {
            sb.append("Marsel\n")
            continue
        }

        val div = divisors(m)
        var flag = false
        if (m > 1) {
            div.add(1)
        }
        for (i in div.indices) {
            if (div[i] >= k) {
                flag = true
                break
            }
        }

        if (flag) {
            sb.append("Timur\n")
        } else {
            sb.append("Marsel\n")
        }
    }

    print(sb)
}
